const { rooms, initializeRooms } = require('../models/roomModel');

const getRooms = (req, res) => {
  res.json(rooms);
};

const bookRooms = (req, res) => {
  const { count } = req.body;
  const numRooms = parseInt(count, 10);

  if (numRooms < 1 || numRooms > 5) {
    return res.status(400).json({ message: 'You can book between 1 to 5 rooms only.' });
  }

  let bookedRooms = [];
  for (let floor = 1; floor <= 10 && bookedRooms.length < numRooms; floor++) {
    const floorRooms = rooms.filter((room) => room.floor === floor && !room.booked);
    while (floorRooms.length > 0 && bookedRooms.length < numRooms) {
      const room = floorRooms.shift();
      room.booked = true;
      bookedRooms.push(room.number);
    }
  }

  if (bookedRooms.length < numRooms) {
    return res.status(400).json({ message: 'Not enough rooms available.' });
  }

  res.json({ bookedRooms });
};

const randomizeRooms = (req, res) => {
  rooms.forEach((room) => {
    // Randomly book/unbook rooms
    room.booked = Math.random() > 0.3; // 70% chance of booking
  });

  res.json({ message: 'Rooms randomized.', rooms });
};

const resetRooms = (req, res) => {
  initializeRooms(); // Reset all rooms to initial state
  res.json({ message: 'Rooms reset successfully.', rooms });
};

module.exports = { getRooms, bookRooms, randomizeRooms, resetRooms };
